async function revokePermission(permissionId, actorId, reason) {
  const permission = await db.permissions.findById(permissionId);
  if (!permission || permission.revokedAt) {
    return { ok: false, message: 'permission not found or already revoked' };
  }

  permission.revokedAt = new Date().toISOString();
  permission.revokedBy = actorId;
  await db.permissions.save(permission);

  await cache.invalidate(`perm:${permission.clientId}:${permission.action}`);

  await auditLog.write({
    event: 'permission_revoked',
    permissionId,
    actor: actorId,
    timestamp: permission.revokedAt,
    details: { reason }
  });

  return { ok: true };
}

function isPermissionActive(permission) {
  if (!permission) return false;
  return permission.revokedAt === null;
}

